}
// ---------------------------------------------------------------- Rocks from Space hazards (pure functions of world time)
function isTimed(L) { return L.movers.length > 0 || L.rings.length > 0 || L.hail.length > 0 || L.rocks.some((r) => r.range > 0); }
function rockPos(L, r, t) {
