function startFlight(st, d, kick, L) {
  const [dx, dy] = DIRS[d];
  st.ghost = -1;
  if (st.ride && L) st.ghost = st.ride.m;
  if (st.ride && L) {   // leaving a moving platform: line up with the nearest free lane across the launch direction
